      {"id": "wb-2.1-01", "type": "mc", "diff": 1, "skill": "expression-words", "source": "wb", "lang": "en", "q": "A bag contains y counters. I take 5 counters out. Which expression shows how many are left?", "svg": null, "choices": ["y + 5", "y − 5", "5 − y", "5y"], "answer": 1, "hints": ["Lấy ra nghĩa là số viên tăng hay giảm?", "Em bắt đầu từ y và bớt đi 5 thì viết thế nào?", "Thứ tự trong phép trừ có quan trọng không: y − 5 hay 5 − y?"], "explain": "Số viên ban đầu là y, bớt 5 viên nên còn y − 5. Biểu thức 5 − y đảo ngược thứ tự phép trừ (sai lầm hay gặp).", "why": null},
      {"id": "wb-2.1-02", "type": "text", "diff": 1, "skill": "expression-words", "source": "wb", "lang": "en", "q": "Zalika has a box with c one-dollar coins. She doubles the number of coins in the box. Write an expression for the new number of coins.", "svg": null, "choices": null, "answer": "2c", "accept": ["c×2", "2×c"], "hints": ["Gấp đôi nghĩa là nhân với số nào?", "Viết phép nhân giữa số đó và c.", "Trong đại số, 2 × c thường được viết gọn thế nào?"], "explain": "Gấp đôi nghĩa là nhân với 2, nên số xu mới là 2 × c = 2c.", "why": null},
      {"id": "wb-2.1-03", "type": "mc", "diff": 2, "skill": "expression-brackets", "source": "wb", "lang": "en", "q": "Shen thinks of a number n. He adds 3 to it and then multiplies the result by 8. Which expression is correct?", "svg": null, "choices": ["8n + 3", "8(n + 3)", "3(n + 8)", "n + 3 × 8"], "answer": 1, "hints": ["Phép tính nào xảy ra trước: cộng 3 hay nhân 8?", "Muốn nhân cả (n + 3) với 8 thì cần dùng dấu gì để giữ phần cộng làm trước?", "Đáp án 'n + 3 × 8' sẽ tính phép nào trước theo thứ tự thực hiện phép tính?"], "explain": "Cộng 3 vào n trước rồi mới nhân 8 nên cần ngoặc: 8(n + 3). Viết n + 3 × 8 hay 8n + 3 chỉ nhân 8 với một phần của biểu thức.", "why": null},
      {"id": "wb-2.1-04", "type": "text", "diff": 2, "skill": "expression-words", "source": "wb", "lang": "en", "q": "Shen thinks of a number n. He divides it by 6 and then subtracts 8. Write an expression for the number he gets.", "svg": null, "choices": null, "answer": "n/6-8", "accept": ["(n/6)-8", "-8+n/6", "n÷6-8"], "hints": ["Phép chia n cho 6 được viết dạng phân số thế nào?", "Sau khi chia, em trừ 8 khỏi kết quả đó. Em viết tiếp thế nào?", "Có cần dùng ngoặc không, khi phép chia vốn được làm trước phép trừ?"], "explain": "Chia n cho 6 được n/6, rồi trừ 8 được n/6 − 8.", "why": null},
      {"id": "wb-2.1-05", "type": "text", "diff": 2, "skill": "expression-words", "source": "wb", "lang": "en", "q": "Shen thinks of a number n. He adds 4 to it and then divides the result by 5. Write an expression for the number he gets.", "svg": null, "choices": null, "answer": "(n+4)/5", "accept": ["(4+n)/5", "(n+4)÷5", "(4+n)÷5"], "hints": ["Phép tính nào được thực hiện trước, cộng hay chia?", "Cả (n + 4) bị chia cho 5, không chỉ riêng số 4. Em thể hiện điều đó bằng cách nào?", "Viết (n + 4) rồi chia cho 5 dưới dạng phân số hoặc phép chia."], "explain": "Cộng trước rồi chia, nên dùng ngoặc hoặc gạch phân số: (n + 4)/5 hay (n + 4) ÷ 5.", "why": null},
      {"id": "wb-2.1-06", "type": "mc", "diff": 2, "skill": "expression-fractions", "source": "wb", "lang": "en", "q": "Kim has to write 'one-fifth of x, add 7'. Which expression is correct?", "svg": null, "choices": ["x/5 + 7", "(x + 7)/5", "x/(5 + 7)", "5x + 7"], "answer": 0, "hints": ["'Một phần năm của x' là phần nào của biểu thức? Nó có bao gồm số 7 không?", "Phần nào bị chia cho 5: chỉ x hay cả x + 7?", "Sau khi lấy một phần năm của x, em cộng thêm 7 như thế nào?"], "explain": "Chỉ x được chia cho 5, rồi cộng 7: x/5 + 7. Biểu thức (x + 7)/5 chia cả x + 7 cho 5 nên sai (lỗi của Kim).", "why": null},
      {"id": "wb-2.1-07", "type": "num", "diff": 2, "skill": "expression-cost", "source": "wb", "lang": "en", "q": "Lemons cost $4 per kilogram and rice costs $5 per kilogram. Work out the total cost of 600 g of rice and 750 g of lemons.", "svg": null, "choices": null, "answer": 6, "unitLabel": "$", "hints": ["600 g bằng bao nhiêu ki-lô-gam? Còn 750 g?", "Giá gạo = số kg gạo × 5 và giá chanh = số kg chanh × 4. Tính từng giá.", "Cộng hai khoản tiền lại."], "explain": "600 g = 0,6 kg nên gạo giá 0,6 × 5 = 3 đô la. 750 g = 0,75 kg nên chanh giá 0,75 × 4 = 3 đô la. Tổng = 6 đô la.", "why": null},
      {"id": "wb-2.1-08", "type": "num", "diff": 3, "skill": "expression-perimeter", "source": "wb", "lang": "en", "q": "The longest side of a triangle is a cm. The second side is b cm shorter than the longest. The third side is half as long as the second side. Work out the perimeter when a = 10 and b = 4.", "svg": null, "choices": null, "answer": 19, "unitLabel": "cm", "hints": ["Viết biểu thức cho cạnh thứ hai theo a và b.", "Cạnh thứ ba bằng nửa cạnh thứ hai. Với a = 10, b = 4 các cạnh thứ hai và thứ ba lần lượt là bao nhiêu?", "Cộng ba cạnh lại."], "explain": "Các cạnh: a = 10, a − b = 6, (a − b)/2 = 3. Chu vi = 10 + 6 + 3 = 19 cm.", "why": null},
      {"id": "wb-2.1-09", "type": "mc", "diff": 3, "skill": "expression-simplify", "source": "wb", "lang": "en", "q": "The longest side of a triangle is a cm, the second side is b cm shorter, and the third side is half as long as the second side. Which is the perimeter in simplest form?", "svg": null, "choices": ["2.5a − 1.5b", "3a − 1.5b", "2.5a − 0.5b", "3a − b"], "answer": 0, "hints": ["Viết ba cạnh: a, a − b và (a − b)/2. Chu vi là tổng của ba biểu thức đó.", "Gộp các số hạng chứa a và các số hạng chứa b. Có bao nhiêu 'a' tất cả, tính cả nửa a?", "Hệ số của b: −b rồi −b/2, tổng là bao nhiêu?"], "explain": "Chu vi = a + (a − b) + (a − b)/2 = a + a − b + 0,5a − 0,5b = 2,5a − 1,5b.", "why": null},
      {"id": "wb-2.1-10", "type": "mc", "diff": 3, "skill": "expression-brackets", "source": "wb", "lang": "en", "q": "Sion thinks of a number y. He adds 3 to one-quarter of y, then multiplies the result by 8. Which expression is correct?", "svg": null, "choices": ["4(y/3 + 8)", "8(3y/4 + 4)", "4(3y/8 + 3)", "8(y/4 + 3)"], "answer": 3, "hints": ["'Một phần tư của y' viết thế nào?", "Cộng 3 vào phần đó rồi mới nhân với 8: cần ngoặc quanh phần nào?", "So với các đáp án, tìm biểu thức có dạng 8( … + 3) với phần trong ngoặc là một phần tư của y."], "explain": "Một phần tư của y là y/4, cộng 3 được y/4 + 3, rồi nhân 8 cho 8(y/4 + 3).", "why": null}
