      {"id": "wb-2.2-03", "type": "num", "diff": 2, "skill": "substitute-order", "source": "wb", "lang": "en", "q": "Work out 10 − x/3 when x = 15.", "svg": null, "choices": null, "answer": 5, "hints": ["Thay x = 15. Trong biểu thức này phép chia hay phép trừ làm trước?", "Tính 15 ÷ 3 trước.", "Lấy 10 trừ kết quả vừa tính."], "explain": "10 − x/3 = 10 − 15/3 = 10 − 5 = 5. Lỗi thường gặp: tính (10 − 15) ÷ 3.", "why": null},
      {"id": "wb-2.2-04", "type": "num", "diff": 2, "skill": "substitute-squares", "source": "wb", "lang": "en", "q": "Work out 30 − b² when b = 6.", "svg": null, "choices": null, "answer": -6, "hints": ["b² nghĩa là b × b. Với b = 6 nó bằng bao nhiêu?", "Lũy thừa được làm trước phép trừ.", "Tính 30 trừ kết quả đó; kết quả có thể âm."], "explain": "30 − b² = 30 − 6² = 30 − 36 = −6.", "why": null},
      {"id": "wb-2.2-05", "type": "num", "diff": 2, "skill": "substitute-negative", "source": "wb", "lang": "en", "q": "Work out 5(n³ + 10) when n = −2.", "svg": null, "choices": null, "answer": 10, "hints": ["Thay n = −2. n³ = (−2)³ bằng bao nhiêu, nhớ dấu?", "Cộng 10 vào kết quả đó ở trong ngoặc.", "Cuối cùng nhân kết quả trong ngoặc với 5."], "explain": "n³ = (−2)³ = −8. Trong ngoặc: −8 + 10 = 2. Nhân với 5: 5 × 2 = 10.", "why": null},
      {"id": "wb-2.2-06", "type": "mc", "diff": 2, "skill": "formula-error", "source": "wb", "lang": "en", "q": "Harsha uses V = Ah/3 with A = 6 and h = 12. She writes V = (6 + 12)/3 = 6. What mistake did she make?", "svg": null, "choices": ["She added A and h instead of multiplying", "She divided by 3 before substituting", "She should have squared h", "There is no mistake"], "answer": 0, "hints": ["Trong công thức, Ah viết liền nhau nghĩa là phép tính nào giữa A và h?", "Bạn ấy đã làm phép tính gì giữa 6 và 12?", "Tính lại đúng: 6 × 12 ÷ 3 bằng bao nhiêu? Có khác 6 không?"], "explain": "Ah nghĩa là A × h, nhưng Harsha đã cộng A và h. Đúng ra V = 6 × 12 ÷ 3 = 72 ÷ 3 = 24.", "why": null},
      {"id": "wb-2.2-07", "type": "num", "diff": 3, "skill": "formula-compare", "source": "wb", "lang": "en", "q": "The volume of a pyramid with a triangular base is V = bhl/6. Pyramid A has b = 4 cm, h = 3 cm, l = 16 cm. Pyramid B has b = 6 cm, h = 4 cm, l = 9 cm. What is the larger volume, in cm³?", "svg": null, "choices": null, "answer": 36, "unitLabel": "cm³", "hints": ["Thay số của chóp A vào V = bhl/6. bhl nghĩa là b × h × l.", "Tính tương tự cho chóp B, rồi so sánh hai kết quả.", "Thể tích nào lớn hơn? Chọn giá trị đó."], "explain": "A: V = 4 × 3 × 16 ÷ 6 = 192 ÷ 6 = 32 cm³. B: V = 6 × 4 × 9 ÷ 6 = 216 ÷ 6 = 36 cm³. Chóp B lớn hơn, thể tích 36 cm³.", "why": null},
      {"id": "wb-2.2-08", "type": "mc", "diff": 3, "skill": "change-subject", "source": "wb", "lang": "en", "q": "Make x the subject of the formula y = 2x + t. Which answer is correct?", "svg": null, "choices": ["x = (y + t)/2", "x = 2y + t", "x = (y − t)/2", "x = y − t/2"], "answer": 2, "hints": ["Trong y = 2x + t, x bị tác động bởi những phép tính nào, theo thứ tự?", "Hoàn tác từng phép tính theo thứ tự ngược lại: bước đầu tiên em làm gì với t?", "Sau đó phép nhân với 2 được hoàn tác thế nào? Cả vế phải y − t phải chia cho 2 hay chỉ một phần?"], "explain": "y = 2x + t ⇒ y − t = 2x ⇒ x = (y − t)/2. Cả y − t phải chia cho 2, không chỉ riêng t.", "why": null},
      {"id": "wb-2.2-09", "howto": "Exactly one expression gives a different value when x = −4. Enter that different value (a number, not the expression).", "type": "num", "diff": 3, "skill": "substitute-odd-one-out", "source": "wb", "lang": "en", "q": "When x = −4, five of these expressions have the same value and one is the odd one out:  x² − 7,  (x + 1)²,  −36/x,  x − 5,  2x + 17,  5 − x.  What is the value of the odd one out?", "svg": null, "choices": null, "answer": -9, "hints": ["Thay x = −4 vào từng biểu thức. Bắt đầu với x² − 7: (−4)² bằng bao nhiêu?", "Tính các biểu thức còn lại, chú ý dấu của −36/x và 5 − x.", "Biểu thức nào cho giá trị khác với các biểu thức còn lại? Giá trị đó là gì?"], "explain": "Với x = −4: x² − 7 = 9; (x + 1)² = (−3)² = 9; −36/x = 9; x − 5 = −9; 2x + 17 = 9; 5 − x = 9. Biểu thức x − 5 khác biệt, giá trị là −9.", "why": null},
      {"id": "wb-2.2-10", "type": "num", "diff": 3, "skill": "substitute-formula", "source": "wb", "lang": "en", "q": "The distance travelled is s = ut + ½at², where u is the starting speed, a is the acceleration and t is the time. Work out s when u = 30, a = −4 and t = 10.", "svg": null, "choices": null, "answer": 100, "hints": ["Thay số: ut = 30 × 10 bằng bao nhiêu?", "Tính ½at²: làm lũy thừa t² trước, rồi nhân với a và với ½. Chú ý a âm.", "Cộng hai phần lại, phần thứ hai là số âm."], "explain": "ut = 30 × 10 = 300. ½at² = ½ × (−4) × 10² = ½ × (−4) × 100 = −200. s = 300 − 200 = 100.", "why": null}
